export interface GraphNode {
  id: string;
  group: 'actor' | 'group' | 'location' | 'concept';
  radius?: number;
}

export interface GraphLink {
  source: string;
  target: string;
  relation: string;
}

export interface NetworkGraphData {
  nodes: GraphNode[];
  links: GraphLink[];
}

export interface QuizQuestion {
  id: number;
  question: string;
  options: string[];
  correctAnswerIndex: number;
  explanation: string;
}

export interface Section {
  title: string;
  content: string;
}

export interface SourceReference {
  title: string;
  url?: string;
}

export interface StateData {
  name: string; // e.g., "Zamfara", "Borno"
  spreadRate: number; // 0-100 representing intensity/risk
  summary: string; // Summary based on article
  incidentReport: string; // Specific incident info
  sources: SourceReference[]; // List of intelligence sources with links
  expansionStatus: 'Active Zone' | 'Probable Next Target' | 'Buffer Zone'; // Classification of conflict status
  threatForecast: string; // Defensible prediction logic
  population: string; // Estimated population
  demographics: string; // Ethnic/Social breakdown
}

export interface CourseData {
  title: string;
  summarySections: Section[];
  networkData: NetworkGraphData;
  mapData: StateData[];
  quiz: QuizQuestion[];
  simulationIntro: string;
}

export interface SimulationTurn {
  scenario: string;
  choices: {
    id: string;
    text: string;
  }[];
  feedback?: string;
  scoreDelta?: number;
}

export interface RegionalRisk {
  region: 'North West' | 'North East' | 'North Central';
  infiltrationLevel: number; // 0-100
  status: 'Stable' | 'Vulnerable' | 'Critical' | 'Saturated';
}

export interface WargameTurn {
  turnNumber: number;
  situationReport: string; // General context for this turn
  regionalRisks: RegionalRisk[];
  availableActions: {
    id: string;
    regionTarget: 'North West' | 'North East' | 'North Central';
    type: 'Military' | 'Intel' | 'Development'; // Action type
    description: string;
  }[];
  outcomeAnalysis?: string; // What happened based on last turn
}

import { GoogleGenAI, Type, Schema, Modality } from "@google/genai";
import { CourseData, SimulationTurn, WargameTurn } from '../types';

// Initialize Gemini Client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const courseSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    title: { type: Type.STRING },
    summarySections: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          content: { type: Type.STRING, description: "Markdown supported content" },
        },
        required: ["title", "content"]
      },
    },
    networkData: {
      type: Type.OBJECT,
      properties: {
        nodes: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              group: { type: Type.STRING, enum: ["actor", "group", "location", "concept"] },
            },
            required: ["id", "group"]
          }
        },
        links: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              source: { type: Type.STRING },
              target: { type: Type.STRING },
              relation: { type: Type.STRING },
            },
            required: ["source", "target", "relation"]
          }
        }
      },
      required: ["nodes", "links"]
    },
    mapData: {
      type: Type.ARRAY,
      description: "Data for key Nigerian states involved in the conflict (e.g. Borno, Zamfara, Kaduna, Niger, Katsina, Sokoto)",
      items: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          spreadRate: { type: Type.INTEGER, description: "0 to 100 intensity of Jihadist influence/spread" },
          summary: { type: Type.STRING, description: "Strategic summary of the situation in this state based on the Kachallas article." },
          incidentReport: { type: Type.STRING, description: "A specific recent security incident, kidnapping event, or diffusion activity reported in this location with context." },
          expansionStatus: { 
            type: Type.STRING, 
            enum: ['Active Zone', 'Probable Next Target', 'Buffer Zone'],
            description: "Classify based on recent diffusion trends. 'Probable Next Target' are areas bordering active zones with kinship ties."
          },
          threatForecast: {
            type: Type.STRING,
            description: "A defensible threat forecast explaining WHY this is likely the next expansion node or why it remains a buffer, citing kinship or geography."
          },
          population: { type: Type.STRING, description: "Estimated population of the state (e.g. '5.3 Million')" },
          demographics: { type: Type.STRING, description: "Brief ethnic/social demographics summary (e.g. 'Hausa-Fulani majority with significant...')" },
          sources: { 
            type: Type.ARRAY, 
            description: "List of reputable sources for the incident report.",
            items: { 
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                url: { type: Type.STRING }
              },
              required: ["title"]
            }
          }
        },
        required: ["name", "spreadRate", "summary", "incidentReport", "expansionStatus", "threatForecast", "population", "demographics", "sources"]
      }
    },
    quiz: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.INTEGER },
          question: { type: Type.STRING },
          options: { type: Type.ARRAY, items: { type: Type.STRING } },
          correctAnswerIndex: { type: Type.INTEGER },
          explanation: { type: Type.STRING },
        },
        required: ["id", "question", "options", "correctAnswerIndex", "explanation"]
      }
    },
    simulationIntro: { type: Type.STRING, description: "Introduction text for the roleplay simulation" }
  },
  required: ["title", "summarySections", "networkData", "mapData", "quiz", "simulationIntro"]
};

export const fetchCourseData = async (language: string = 'English'): Promise<CourseData> => {
  const prompt = `
    You are an expert on Nigerian security studies and counter-terrorism.
    Based on the concepts from "Kachallas and Kinship: Understanding Jihadi Expansion and Diffusion in Nigeria" (CTC Sentinel), create an interactive course structure.

    IMPORTANT: Generate all text content in the following language: ${language}.
    If the language is Nigerian Pidgin, use authentic Nigerian Pidgin English.
    If the language is Hausa, Yoruba, or Igbo, ensure accurate translation while maintaining the educational context.

    Key topics to cover:
    1. The role of 'Kachallas' (bandit warlords) and their status.
    2. The 'Jihadi-Bandit Nexus' (Ansaru, ISWAP, JAS).
    3. The role of 'Kinship' and ethnic ties in facilitating or blocking expansion.
    4. Geographic diffusion from North East (Borno/Yobe) to North West (Zamfara, Katsina, Sokoto) and North Central (Niger State).

    Generate:
    1. A 3-part summary (Context, The Nexus, Strategic Implications).
    2. Data for a network graph showing relationships between Groups (ISWAP, Ansaru), Actors (Kachallas), and Locations.
    3. Map Data: Identify 6-8 key states involved in the conflict.
       - 'summary': Provide a concise strategic summary of the security situation in this state based on the article.
       - 'incidentReport': Describe a SPECIFIC incident or recent trend (e.g. "Abduction of students in Kuriga", "Ansaru preaching in Birnin Gwari") linked to this location.
       - 'population': Estimated population.
       - 'sources': Cite specific reports if possible (e.g. "CTC Sentinel", "Daily Trust").
       - 'expansionStatus': Identify 'Probable Next Target' based on diffusion vectors.
    4. 4 Quiz questions testing comprehension.
    5. An intro for a policy simulation where the user plays a government strategist. Set the stage for a scenario where intelligence reports indicate a Kachalla is considering defecting from JAS to ISWAP.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: courseSchema,
        systemInstruction: "You are an educational content generator specializing in geopolitical conflict analysis."
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as CourseData;
    }
    throw new Error("Empty response from Gemini");
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

const simulationSchema: Schema = {
