                type: Type.OBJECT,
                properties: {
                    id: { type: Type.STRING },
                    text: { type: Type.STRING }
                },
                required: ["id", "text"]
            }
        },
        feedback: { type: Type.STRING },
        scoreDelta: { type: Type.INTEGER }
    },
    required: ["scenario", "choices"]
};

export const fetchSimulationTurn = async (previousContext: string, choiceId?: string, language: string = 'English'): Promise<SimulationTurn> => {
    const prompt = `
      Continue the policy simulation regarding the security crisis in North West Nigeria.

      IMPORTANT: Generate the content in ${language}.

      Previous Context/History: ${previousContext}
      User's Last Choice: ${choiceId || "Start of Simulation"}

      **MANDATORY SCENARIO SCRIPT (Implement this flow):**

      1. PHASE 1 (If this is the Start of Simulation or Turn 1):
         - Present the "Expansion Decision Point" Scenario: "Intelligence indicates a kachalla is defecting from JAS-aligned cells to ISWAP influence due to family disputes and resource access."
         - User Task: Decide the nature of this realignment.
         - Choices MUST be structured as:
           A) Assess as Opportunistic Realignment (Likelihood: High / Impact: Low)
           B) Assess as Strategic ISWAP Expansion (Likelihood: Med / Impact: High)
           C) Assess as Temporary Alliance (Likelihood: Low / Impact: Med)

      2. PHASE 2 (If the user just made the decision in Phase 1):
         - Trigger a "Midway Inject" (Start the scenario text with "URGENT MIDWAY INJECT:").
         - Text: "New intel: Marriage alliance confirmed between families and movement of fighters across a border LGA."
         - User Task: Revise assessment based on this new kinship indicator.
         - Choices MUST reflect tactical adjustments (e.g., "Confirm Strategic Expansion & Deploy Task Force", "Treat as Localized Kinship Event & Monitor").

      3. PHASE 3 (Subsequent turns):
         - Continue naturally based on the consequences of the user's previous choices (e.g. if they ignored the strategic expansion, show the spread increasing).
         - Focus on the 'Kinship' and 'Diffusion' themes.

      Provide a 'scoreDelta' between -10 (bad outcome) and +10 (good outcome).
    `;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: {
                responseMimeType: 'application/json',
                responseSchema: simulationSchema,
            }
        });
        if(response.text) {
            return JSON.parse(response.text) as SimulationTurn;
        }
        throw new Error("Empty simulation response");
    } catch (error) {
        console.error("Simulation API Error", error);
        throw error;
    }
}

