  "Kaduna": { lat: 10.5105, lng: 7.4165 },
  "Zamfara": { lat: 12.1628, lng: 6.6613 }, // Gusau
  "Sokoto": { lat: 13.0059, lng: 5.2476 },
  "Kebbi": { lat: 11.4389, lng: 4.2261 },
