                        </div>
                    </div>

                    {/* Footer / Classification */}
                    <div className="text-center pt-4 border-t border-brand-cream/5">
                        <span className={`text-[10px] font-bold uppercase tracking-widest px-3 py-1.5 rounded-full border ${
                            selectedState.expansionStatus === 'Probable Next Target' 
                                ? 'bg-yellow-900/30 text-yellow-400 border-yellow-500/50' 
                                : 'bg-brand-olive/20 text-brand-olive border-brand-olive/30'
                        }`}>
                            Status: {selectedState.expansionStatus}
                        </span>
                    </div>

                </div>
            ) : (
                <div className="h-full flex flex-col items-center justify-center text-brand-cream/30 text-center">
                    <Target className="w-16 h-16 mb-6 opacity-20 animate-pulse-slow" />
                    <h4 className="text-lg font-bold text-brand-cream/50 mb-2">Awaiting Target Selection</h4>
                    <p className="text-sm max-w-xs mx-auto font-light">
                        Select a highlighted region on the map to access the classified dossier including strategic summaries and incident logs.
                    </p>
                </div>
            )}
            </div>
        </div>
      </div>
    </div>
  );
};

const FilterButton: React.FC<{ active: boolean; onClick: () => void; label: string; icon?: React.ReactNode }> = ({ active, onClick, label, icon }) => (
    <button 
        onClick={onClick}
        className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-bold uppercase tracking-wider border transition-all duration-300 ${
            active 
            ? 'bg-brand-cream text-brand-black border-brand-cream shadow-[0_0_10px_rgba(240,231,194,0.3)]' 
            : 'bg-transparent text-brand-cream/50 border-brand-cream/10 hover:border-brand-cream/30 hover:text-brand-cream'
        }`}
    >
        {icon} {label}
    </button>
);

export default MapOverview;

import React, { useState } from 'react';
import { QuizQuestion } from '../types';
import { CheckCircle, XCircle, AlertCircle, RefreshCw, ArrowRight } from 'lucide-react';

interface Props {
  questions: QuizQuestion[];
}

const Quiz: React.FC<Props> = ({ questions }) => {
  const [currentIdx, setCurrentIdx] = useState(0);
  const [selectedOption, setSelectedOption] = useState<number | null>(null);
  const [isAnswered, setIsAnswered] = useState(false);
  const [score, setScore] = useState(0);
  const [showSummary, setShowSummary] = useState(false);

  const currentQ = questions[currentIdx];

  const handleOptionClick = (idx: number) => {
    if (isAnswered) return;
    setSelectedOption(idx);
    setIsAnswered(true);
    if (idx === currentQ.correctAnswerIndex) {
      setScore(prev => prev + 1);
    }
  };

  const nextQuestion = () => {
    if (currentIdx < questions.length - 1) {
      setCurrentIdx(prev => prev + 1);
      setSelectedOption(null);
      setIsAnswered(false);
    } else {
      setShowSummary(true);
    }
  };

  const resetQuiz = () => {
    setCurrentIdx(0);
    setScore(0);
    setShowSummary(false);
    setIsAnswered(false);
    setSelectedOption(null);
  };

  if (showSummary) {
    return (
      <div className="max-w-md mx-auto mt-12 glass-panel p-12 rounded-2xl text-center border border-brand-cream/10 shadow-2xl">
        <div className="w-32 h-32 mx-auto bg-brand-black rounded-full flex items-center justify-center mb-8 border-4 border-brand-red shadow-[0_0_30px_rgba(149,65,48,0.3)]">
            <span className="text-5xl font-black text-white">{Math.round((score / questions.length) * 100)}%</span>
        </div>
        <h2 className="text-3xl font-bold text-brand-cream mb-2">Assessment Complete</h2>
        <p className="text-brand-cream/60 mb-8 font-light">Dossier review score: {score} / {questions.length}</p>
        <button 
            onClick={resetQuiz}
            className="px-8 py-3 bg-brand-red text-white rounded-lg hover:bg-red-700 transition font-bold uppercase tracking-wider flex items-center justify-center gap-2 mx-auto w-full"
        >
            <RefreshCw className="w-4 h-4" /> Restart
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-2xl mx-auto py-8">
      <div className="mb-8 flex justify-between items-end">
        <div>
            <span className="text-brand-red font-mono text-xs uppercase tracking-widest block mb-1">Incoming Query</span>
            <span className="text-2xl font-bold text-brand-cream">0{currentIdx + 1} <span className="text-brand-cream/20">/ 0{questions.length}</span></span>
        </div>
        <div className="text-right">
             <span className="text-xs text-brand-cream/40 uppercase tracking-widest">Current Score</span>
             <div className="text-xl font-mono text-brand-olive">{score}</div>
        </div>
      </div>

      <div className="glass-panel p-8 rounded-2xl border border-brand-cream/10 relative overflow-hidden">
         {/* Background accent */}
         <div className="absolute -top-10 -right-10 w-40 h-40 bg-brand-red/10 rounded-full blur-3xl pointer-events-none"></div>

        <h3 className="text-xl font-bold text-white mb-8 leading-relaxed relative z-10">{currentQ.question}</h3>

        <div className="space-y-4 relative z-10">
          {currentQ.options.map((opt, idx) => {
            let baseStyle = "w-full text-left p-5 rounded-xl border transition-all duration-300 flex items-center justify-between group ";

            if (isAnswered) {
                if (idx === currentQ.correctAnswerIndex) {
                    baseStyle += "border-brand-olive bg-brand-olive/20 text-brand-cream shadow-[0_0_15px_rgba(104,116,81,0.3)] ";
                } else if (idx === selectedOption) {
                    baseStyle += "border-brand-red bg-brand-red/20 text-brand-red ";
                } else {
                    baseStyle += "border-transparent bg-brand-black/40 text-brand-cream/20 opacity-50 ";
                }
            } else {
                baseStyle += "border-brand-cream/5 bg-brand-black/20 hover:bg-brand-cream/5 hover:border-brand-cream/20 text-brand-cream/70 hover:text-brand-cream ";
            }

            return (
              <button
                key={idx}
                onClick={() => handleOptionClick(idx)}
                disabled={isAnswered}
                className={baseStyle}
              >
                <span className="font-light tracking-wide">{opt}</span>
                {isAnswered && idx === currentQ.correctAnswerIndex && <CheckCircle className="w-5 h-5 text-brand-olive" />}
                {isAnswered && idx === selectedOption && idx !== currentQ.correctAnswerIndex && <XCircle className="w-5 h-5 text-brand-red" />}
                {!isAnswered && <div className={`w-3 h-3 rounded-full border border-brand-cream/30 group-hover:border-brand-cream transition-colors`}></div>}
              </button>
            );
          })}
        </div>

        {isAnswered && (
          <div className="mt-8 animate-in fade-in slide-in-from-bottom-2">
            <div className="p-5 bg-brand-olive/10 rounded-xl border-l-2 border-brand-olive flex items-start gap-4 mb-6">
                <AlertCircle className="w-5 h-5 text-brand-olive shrink-0 mt-0.5" />
                <div>
                    <p className="font-bold text-brand-olive text-xs uppercase tracking-wider mb-1">Intel Analysis</p>
                    <p className="text-brand-cream/80 text-sm leading-relaxed">{currentQ.explanation}</p>
                </div>
            </div>

            <div className="flex justify-end">
                <button
                    onClick={nextQuestion}
                    className="px-8 py-3 bg-brand-cream text-brand-black rounded-lg hover:bg-white transition font-bold uppercase tracking-wider shadow-lg flex items-center gap-2"
                >
                    {currentIdx < questions.length - 1 ? "Next Query" : "Complete Assessment"}
                    <ArrowRight className="w-4 h-4" />
                </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default Quiz;

import React, { useState, useEffect, useRef } from 'react';
import { StateData } from '../types';
import { Info, ExternalLink, Target, AlertTriangle, Users, Share2, Crown, X, FileText, Siren } from 'lucide-react';
import L from 'leaflet';

interface Props {
  data: StateData[];
}

// Real coordinates for Nigerian States (centroids or capitals)
const STATE_COORDINATES: Record<string, { lat: number; lng: number }> = {
  "Borno": { lat: 11.8333, lng: 13.1500 }, // Maiduguri
  "Yobe": { lat: 12.0000, lng: 11.5000 },
  "Adamawa": { lat: 9.3333, lng: 12.5000 },
  "Gombe": { lat: 10.2897, lng: 11.1673 },
  "Bauchi": { lat: 10.3103, lng: 9.8439 },
  "Jigawa": { lat: 12.2280, lng: 9.5616 },
  "Kano": { lat: 11.9964, lng: 8.5167 },
  "Katsina": { lat: 12.9894, lng: 7.6006 },
  "Kaduna": { lat: 10.5105, lng: 7.4165 },
  "Zamfara": { lat: 12.1628, lng: 6.6613 }, // Gusau
  "Sokoto": { lat: 13.0059, lng: 5.2476 },
  "Kebbi": { lat: 11.4389, lng: 4.2261 },
  "Niger": { lat: 9.9309, lng: 5.5983 },
  "FCT": { lat: 9.0765, lng: 7.3986 },
  "Abuja": { lat: 9.0765, lng: 7.3986 },
  "Plateau": { lat: 9.2182, lng: 9.5179 },
  "Nasarawa": { lat: 8.4998, lng: 8.1997 },
  "Benue": { lat: 7.3369, lng: 8.7404 },
  "Taraba": { lat: 8.8937, lng: 11.3596 },
  "Kogi": { lat: 7.7337, lng: 6.6906 },
  "Kwara": { lat: 8.9669, lng: 4.3874 },
  "Lagos": { lat: 6.5244, lng: 3.3792 },
  "Ogun": { lat: 6.9075, lng: 3.5813 },
};

const KINSHIP_CORRIDORS = [
    ["Zamfara", "Katsina"],
    ["Zamfara", "Sokoto"],
    ["Katsina", "Kaduna"],
    ["Kaduna", "Niger"],
    ["Niger", "FCT"],
    ["Borno", "Yobe"],
    ["Yobe", "Jigawa"],
    ["Bauchi", "Plateau"],
];

const MapOverview: React.FC<Props> = ({ data }) => {
  const [selectedState, setSelectedState] = useState<StateData | null>(null);
  const [layers, setLayers] = useState({
      boundaries: true,
      presence: true,
      leadership: false,
      kinship: true,
  });

  const mapRef = useRef<HTMLDivElement>(null);
  const leafletMap = useRef<L.Map | null>(null);
  const layerGroups = useRef<Record<string, L.LayerGroup>>({});

  const getIntensityColor = (rate: number) => {
    if (rate >= 75) return '#954130'; // Red
    if (rate >= 40) return '#F59E0B'; // Amber
    return '#687451'; // Olive
  };

  const toggleLayer = (key: keyof typeof layers) => {
      setLayers(prev => ({ ...prev, [key]: !prev[key] }));
  };

  // Initialize Map
  useEffect(() => {
    if (!mapRef.current || leafletMap.current) return;

    const map = L.map(mapRef.current, {
        center: [10.5, 8.0], // Centered on Nigeria
        zoom: 6,
        zoomControl: false,
        attributionControl: false,
        scrollWheelZoom: false, // Prevent accidental scrolling
    });

    // Dark Matter Tiles (CartoDB) - Looks cinematic and professional
    L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png', {
        maxZoom: 19,
        subdomains: 'abcd',
    }).addTo(map);

    // Custom attribution
    L.control.attribution({ prefix: false }).addAttribution('&copy; OpenStreetMap &copy; CartoDB').addTo(map);
    L.control.zoom({ position: 'topright' }).addTo(map);

    // Initialize Layer Groups
    layerGroups.current = {
        presence: L.layerGroup().addTo(map),
        kinship: L.layerGroup().addTo(map),
    };

    leafletMap.current = map;

    return () => {
        map.remove();
        leafletMap.current = null;
    };
  }, []);

  // Update Map Layers
  useEffect(() => {
      if (!leafletMap.current) return;

      const map = leafletMap.current;
      const lg = layerGroups.current;

      // Clear existing layers
      lg.presence.clearLayers();
      lg.kinship.clearLayers();

      // --- PRESENCE LAYER (Circles) ---
      if (layers.presence) {
        data.forEach(state => {
            const coords = Object.entries(STATE_COORDINATES).find(([key]) => state.name.includes(key))?.[1];
            if (!coords) return;

            const color = getIntensityColor(state.spreadRate);
            const isTarget = state.expansionStatus === 'Probable Next Target';
            const isHighThreat = state.spreadRate > 80;
            const radius = 25000 + (state.spreadRate * 500); // 25km base + spread

            // 1. The Large Area Circle
            const circle = L.circle([coords.lat, coords.lng], {
                color: isTarget ? '#EAB308' : color, // Yellow for targets
                fillColor: color,
                fillOpacity: isTarget ? 0.2 : 0.4,
                radius: radius,
                weight: isTarget ? 2 : 1,
                dashArray: isTarget ? '5, 5' : undefined,
                interactive: true 
            });

            // 2. The Visual Pulse Marker (Non-Interactive to pass clicks through)
            if (isTarget || isHighThreat) {
                 const pulseColorClass = isTarget ? 'bg-yellow-500/40' : 'bg-red-500/40';
                 const centerColorClass = isTarget ? 'bg-yellow-600/60 shadow-[0_0_15px_#EAB308]' : 'bg-red-600/60 shadow-[0_0_15px_#EF4444]';

                 const pulseIcon = L.divIcon({
                    className: 'custom-div-icon',
                    html: `
                      <div class="relative w-full h-full flex items-center justify-center pointer-events-none">
                         <div class="absolute w-[300%] h-[300%] ${pulseColorClass} rounded-full animate-ping opacity-60"></div>
                         <div class="absolute w-full h-full ${centerColorClass} rounded-full border border-white/20 shadow-lg"></div>
                      </div>
                    `,
                    iconSize: [20, 20], 
                    iconAnchor: [10, 10]
                 });

                 // Visual marker sits at default or specified z-index.
                 // We disable interaction on the visual so it doesn't block the hitbox if layers overlap weirdly,
                 // but since we are putting hitbox ABOVE, this is just a fallback.
                 const marker = L.marker([coords.lat, coords.lng], { 
                     icon: pulseIcon,
                     zIndexOffset: 1000, 
                     interactive: false 
                 });
                 marker.addTo(lg.presence);

                 // 3. The Invisible Hit Box (Guaranteed Click Target)
                 // REPLACEMENT: Use L.marker with a transparent divIcon instead of L.circleMarker.
                 // L.marker exists in the markerPane (zIndex ~600 + offset), allowing us to strictly control Z-order
                 // via zIndexOffset. We set it very high (2000) to ensure it is the top-most capture element.
                 const hitBoxIcon = L.divIcon({
                     className: 'hitbox-icon', 
                     html: '<div style="width: 100%; height: 100%; background: transparent; cursor: pointer;"></div>',
                     iconSize: [50, 50], // Large 50px clickable area
                     iconAnchor: [25, 25]
                 });

                 const hitBox = L.marker([coords.lat, coords.lng], {
                     icon: hitBoxIcon,
                     zIndexOffset: 2000, // VERY HIGH PRIORITY
                     interactive: true
                 });

                 hitBox.on('click', (e) => {
                     L.DomEvent.stopPropagation(e.originalEvent);
                     L.DomEvent.preventDefault(e.originalEvent);
                     console.log("Hitbox clicked:", state.name); 
                     setSelectedState(state);
                     map.flyTo([coords.lat, coords.lng], 8, { duration: 1.5 });
                 });

                 hitBox.addTo(lg.presence);
            }

            // Fallback click on the large circle
            circle.on('click', (e) => {
                L.DomEvent.stopPropagation(e.originalEvent);
                setSelectedState(state);
                map.flyTo([coords.lat, coords.lng], 8, { duration: 1.5 });
            });

            circle.bindTooltip(`
                <div class="font-sans text-xs uppercase tracking-wider font-bold">
                    ${state.name} <br/>
                    <span style="color: ${isTarget ? '#EAB308' : color}">Spread: ${state.spreadRate}%</span>
                </div>
            `, { 
                permanent: false, 
                direction: 'top',
                className: 'glass-panel text-white border-0'
            });

            lg.presence.addLayer(circle);

            // Leadership Icons
            if (layers.leadership && state.spreadRate > 40) {
                 const icon = L.divIcon({
                    className: 'custom-div-icon',
                    html: `<div style="color: #F0E7C2; background: #02120C; border-radius: 50%; padding: 2px; border: 1px solid #954130;"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M2 4l3 12h14l3-12-6 7-4-7-4 7-6-7zm3 16h14"/></svg></div>`,
                    iconSize: [20, 20],
                    iconAnchor: [10, 10]
                 });
                 L.marker([coords.lat + 0.1, coords.lng + 0.1], { icon, zIndexOffset: 1100 }).addTo(lg.presence);
            }
        });
      }

      // --- KINSHIP LAYER (Polylines) ---
      if (layers.kinship) {
          KINSHIP_CORRIDORS.forEach(([start, end]) => {
              const startC = Object.entries(STATE_COORDINATES).find(([k]) => start.includes(k))?.[1];
              const endC = Object.entries(STATE_COORDINATES).find(([k]) => end.includes(k))?.[1];

              if (startC && endC) {
                const line = L.polyline([[startC.lat, startC.lng], [endC.lat, endC.lng]], {
                    color: '#FFFFFF', // White for kinship
                    weight: 2, // Slightly thicker for visibility
                    dashArray: '5, 8', // Distinct dashes
                    opacity: 0.5
                });
                lg.kinship.addLayer(line);
              }
          });
      }

  }, [data, layers]);

  // Handle External Selections
  useEffect(() => {
    if (leafletMap.current && selectedState) {
         const coords = Object.entries(STATE_COORDINATES).find(([key]) => selectedState.name.includes(key))?.[1];
         if(coords) leafletMap.current.flyTo([coords.lat, coords.lng], 7);
    }
  }, [selectedState]);


  return (
    <div className="flex flex-col lg:flex-row gap-6 h-[800px] lg:h-[700px]">
      <div className="w-full lg:w-2/3 flex flex-col gap-4 h-full">
        {/* Controls Bar */}
        <div className="glass-panel p-4 rounded-xl flex flex-wrap gap-4 items-center justify-between shrink-0">
            <div className="flex items-center gap-2">
                 <div className="w-2 h-2 rounded-full bg-red-500 animate-pulse"></div>
                 <span className="text-xs font-bold uppercase tracking-widest text-brand-cream/70">Live Uplink Active</span>
            </div>

            <div className="flex gap-2 flex-wrap">
                <FilterButton active={layers.presence} onClick={() => toggleLayer('presence')} label="Jihadist" icon={<Target className="w-3 h-3"/>} />
                <FilterButton active={layers.leadership} onClick={() => toggleLayer('leadership')} label="Command" icon={<Crown className="w-3 h-3"/>} />
                <FilterButton active={layers.kinship} onClick={() => toggleLayer('kinship')} label="Kinship" icon={<Share2 className="w-3 h-3"/>} />
            </div>
        </div>

        {/* Interactive Map Container */}
        <div className="glass-panel p-1 rounded-xl relative flex-1 overflow-hidden group border border-brand-cream/10 shadow-2xl">
            <div className="absolute top-4 left-4 z-[400] pointer-events-none">
                 <h3 className="text-xl font-black text-brand-cream/80 tracking-widest uppercase drop-shadow-md">STRATEGIC MAP <span className="text-brand-red">UPLINK</span></h3>
                 <p className="text-[10px] text-brand-cream/50 font-mono">LIVE SATELLITE FEED // LAT: 10.51 // LNG: 7.41</p>
            </div>

            {/* Leaflet Map Target - Ensure Z-Index allows clicks */}
            <div ref={mapRef} className="w-full h-full rounded-lg bg-[#02120C] relative z-0"></div>

            {/* Vignette Overlay for cinematic look - Pointer events none allows clicks to pass through */}
            <div className="absolute inset-0 pointer-events-none shadow-[inset_0_0_100px_rgba(2,18,12,0.9)] z-[300]"></div>
        </div>
      </div>

      <div className="w-full lg:w-1/3 h-full">
        <div className="glass-panel p-6 rounded-xl h-full flex flex-col relative overflow-hidden">
            <div className="absolute top-0 right-0 p-4 opacity-10">
                <Target className="w-24 h-24 text-brand-red" />
            </div>

            <div className="flex flex-col gap-4 mb-4 border-b border-brand-cream/10 pb-4 shrink-0 relative z-10">
                <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                        <Info className="w-5 h-5 text-brand-red" />
                        <h3 className="font-bold text-brand-cream uppercase tracking-wide">
                            {selectedState ? selectedState.name : `Sector Analysis`}
                        </h3>
                    </div>
                    {selectedState && (
                        <button onClick={() => { setSelectedState(null); }} className="text-brand-cream/50 hover:text-brand-red">
                            <X className="w-5 h-5" />
                        </button>
                    )}
                </div>
            </div>

            <div className="flex-1 overflow-y-auto scrollbar-thin pr-2 relative z-10">
            {selectedState ? (
                <div className="animate-in fade-in slide-in-from-right-4 duration-300 space-y-6">

                    {/* 1. Article Summary */}
                    <div className="p-4 bg-brand-black/40 rounded-lg border border-brand-cream/10">
                        <h5 className="text-xs font-bold text-brand-cream/50 uppercase tracking-wider mb-2 flex items-center gap-2">
                            <FileText className="w-3 h-3" /> Strategic Context
                        </h5>
                        <p className="text-brand-cream/90 text-sm leading-relaxed font-light">
                            {selectedState.summary}
                        </p>
                    </div>

                    {/* 2. Incident Report */}
                    <div className="p-4 bg-brand-red/10 rounded-lg border border-brand-red/20 relative overflow-hidden">
                        <div className="absolute top-0 right-0 p-2 opacity-10"><Siren className="w-8 h-8 text-brand-red"/></div>
                        <h5 className="text-xs font-bold text-brand-red uppercase tracking-wider mb-2 flex items-center gap-2">
                            <AlertTriangle className="w-3 h-3" /> Incident Report
                        </h5>
                        <p className="text-brand-cream text-sm mb-4">
                            {selectedState.incidentReport}
                        </p>

                        {selectedState.sources && selectedState.sources.length > 0 && (
                            <div className="mt-2 border-t border-brand-red/20 pt-2">
                                <span className="text-[10px] uppercase text-brand-red/60 font-bold block mb-1">Citations</span>
                                <ul className="space-y-1">
                                    {selectedState.sources.map((source, idx) => (
                                        <li key={idx}>
                                            {source.url ? (
                                                <a href={source.url} target="_blank" rel="noopener noreferrer" className="text-xs text-brand-cream/60 hover:text-brand-cream underline underline-offset-2 flex items-center gap-1">
                                                    {source.title} <ExternalLink className="w-2 h-2" />
                                                </a>
                                            ) : (
                                                <span className="text-xs text-brand-cream/60">{source.title}</span>
                                            )}
                                        </li>
                                    ))}
                                </ul>
                            </div>
                        )}
                    </div>

                    {/* 3. Population */}
                    <div className="p-4 bg-brand-olive/10 rounded-lg border border-brand-olive/20 flex justify-between items-center">
                        <div>
                            <h5 className="text-xs font-bold text-brand-olive uppercase tracking-wider mb-1 flex items-center gap-2">
                                <Users className="w-3 h-3" /> Est. Population
                            </h5>
                            <p className="text-xl font-bold text-brand-cream">{selectedState.population}</p>
                        </div>
                        <div className="text-right">
                             <div className="text-[10px] font-bold uppercase text-brand-cream/40 mb-1">Threat Level</div>
                             <div className="text-xl font-bold font-mono" style={{ color: getIntensityColor(selectedState.spreadRate) }}>
                                 {selectedState.spreadRate}%
                             </div>
                        </div>
                    </div>

                    {/* Footer / Classification */}
                    <div className="text-center pt-4 border-t border-brand-cream/5">
                        <span className={`text-[10px] font-bold uppercase tracking-widest px-3 py-1.5 rounded-full border ${
                            selectedState.expansionStatus === 'Probable Next Target' 
                                ? 'bg-yellow-900/30 text-yellow-400 border-yellow-500/50' 
                                : 'bg-brand-olive/20 text-brand-olive border-brand-olive/30'
                        }`}>
                            Status: {selectedState.expansionStatus}
                        </span>
                    </div>

