import React, { useState, useEffect, useRef } from 'react';
import { Section } from '../types';
import { Volume2, Square, PauseCircle, Play, Activity, Loader2, Globe, ExternalLink } from 'lucide-react';
import { generateAudio } from '../services/geminiService';

interface Props {
  sections: Section[];
  language: string;
}

// Helper: Decode Base64
function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

// Helper: Decode Audio Data (PCM to AudioBuffer)
// Using 24kHz as per high-quality requirement
async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number = 24000,
  numChannels: number = 1,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const ContentReader: React.FC<Props> = ({ sections, language }) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [audioContext, setAudioContext] = useState<AudioContext | null>(null);
  const [audioSource, setAudioSource] = useState<AudioBufferSourceNode | null>(null);
  const [audioBuffer, setAudioBuffer] = useState<AudioBuffer | null>(null);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (audioSource) audioSource.stop();
      if (audioContext) audioContext.close();
    };
  }, []); // Only on mount/unmount

  // Reset audio when content or language changes
  useEffect(() => {
    stopPlayback();
    setAudioBuffer(null);
    if (audioContext) {
        audioContext.close();
        setAudioContext(null);
    }
  }, [sections, language]);

  const stopPlayback = () => {
    if (audioSource) {
      try {
        audioSource.stop();
      } catch (e) {
        // Ignore errors if already stopped
      }
      setAudioSource(null);
    }
    setIsPlaying(false);
  };

  const handleSpeak = async () => {
    // If playing, stop it
    if (isPlaying) {
      stopPlayback();
      return;
    }

    // If we have buffer cached, just play it
    if (audioBuffer && audioContext) {
      playBuffer(audioBuffer, audioContext);
      return;
    }

    // Otherwise generate
    setIsLoading(true);
    try {
        // Concatenate text for a seamless briefing
        const fullText = sections.map(s => `${s.title}. ${s.content}`).join(" ... Next Section ... ");

        const base64Audio = await generateAudio(fullText, language);
        const pcmBytes = decodeBase64(base64Audio);

        // Initialize Audio Context with 24kHz sample rate (High Quality requirement)
        const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        const buffer = await decodeAudioData(pcmBytes, ctx, 24000, 1);

        setAudioContext(ctx);
        setAudioBuffer(buffer);
        playBuffer(buffer, ctx);

    } catch (e) {
        console.error("Playback failed", e);
    } finally {
        setIsLoading(false);
    }
  };

  const playBuffer = (buffer: AudioBuffer, ctx: AudioContext) => {
    // Re-create source node every time we play (they are one-time use)
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(ctx.destination);

    source.onended = () => {
      setIsPlaying(false);
      setAudioSource(null);
    };

    source.start();
    setAudioSource(source);
    setIsPlaying(true);
  };

  return (
    <div className="grid md:grid-cols-12 gap-8">
      <div className="md:col-span-8 space-y-6">
        {/* Audio Control Bar */}
        <div className="flex justify-between items-center glass-panel p-6 rounded-xl relative overflow-hidden group">
            <div className="absolute top-0 left-0 w-1 h-full bg-brand-red"></div>
            <div className="relative z-10">
                <h2 className="font-bold text-brand-cream text-lg tracking-wide uppercase">Executive Briefing</h2>
                <p className="text-xs text-brand-cream/50 flex items-center gap-2">
                   {isLoading ? 'Establishing secure uplink...' : `Neural Audio Link Available (${language} Mode)`}
                </p>
            </div>
            <button 
                onClick={handleSpeak}
                disabled={isLoading}
                className={`relative z-10 flex items-center gap-2 px-6 py-2.5 rounded-lg font-bold text-xs uppercase tracking-wider transition-all duration-300 border ${
                    isPlaying 
                    ? 'bg-brand-red/10 text-brand-red border-brand-red animate-pulse' 
                    : 'bg-brand-cream text-brand-black border-transparent hover:bg-white hover:shadow-[0_0_15px_rgba(255,255,255,0.3)]'
                } disabled:opacity-50 disabled:cursor-wait`}
            >
                {isLoading ? (
                    <>
                       <Loader2 className="w-3 h-3 animate-spin" />
                       <span>Loading...</span>
                    </>
                ) : isPlaying ? (
                    <>
                        <Square className="w-3 h-3 fill-current" /> 
                        <span>Stop Briefing</span>
                    </>
                ) : (
                    <>
                        <Volume2 className="w-3 h-3" /> 
                        <span>Play Audio</span>
                    </>
                )}
            </button>
        </div>

        {sections.map((section, idx) => (
          <div key={idx} className="glass-panel p-8 rounded-xl relative hover:border-brand-red/30 transition-colors duration-500">
             {/* Decorative corner */}
             <div className="absolute top-0 right-0 w-16 h-16 bg-gradient-to-bl from-brand-red/10 to-transparent rounded-tr-xl pointer-events-none"></div>

            <h2 className="text-2xl font-black text-brand-cream mb-6 border-b border-brand-cream/10 pb-4 tracking-tight flex items-center gap-3">
                <span className="text-brand-red opacity-50 text-sm font-mono">0{idx + 1}</span>
                {section.title}
