       - 'incidentReport': Describe a SPECIFIC incident or recent trend (e.g. "Abduction of students in Kuriga", "Ansaru preaching in Birnin Gwari") linked to this location.
       - 'population': Estimated population.
       - 'sources': Cite specific reports if possible (e.g. "CTC Sentinel", "Daily Trust").
       - 'expansionStatus': Identify 'Probable Next Target' based on diffusion vectors.
    4. 4 Quiz questions testing comprehension.
    5. An intro for a policy simulation where the user plays a government strategist. Set the stage for a scenario where intelligence reports indicate a Kachalla is considering defecting from JAS to ISWAP.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: courseSchema,
        systemInstruction: "You are an educational content generator specializing in geopolitical conflict analysis."
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as CourseData;
    }
    throw new Error("Empty response from Gemini");
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

