// ------------------------------------------------------------------
// MULTILINGUAL TTS ENGINE
// ------------------------------------------------------------------

/**
 * Multilingual TTS Configuration Matrix
 * 
 * | Language            | Voice Type | Strategy                                          |
 * | ------------------- | ---------- | ------------------------------------------------- |
 * | English             | Kore       | Default neural prosody                            |
 * | Nigerian Pidgin     | Kore       | English TTS slowed, Creole rhythm instruction     |
 * | Yoruba              | Kore       | Slow pace, distinct tonal articulation hint       |
 * | Igbo                | Kore       | Slow pace, syllable break sensitivity             |
 * | Hausa               | Kore       | Moderate pace, emphatic stress patterns           |
 */
const TTS_CONFIG: Record<string, { promptDirective: string }> = {
  'English': { promptDirective: 'Speak clearly and naturally: ' },
  'Nigerian Pidgin': { promptDirective: 'Speak in Nigerian Pidgin English with a slightly slow, rhythmic creole cadence: ' },
  'Yoruba': { promptDirective: 'Speak in Yoruba with careful tonal articulation and a slower pace: ' },
  'Igbo': { promptDirective: 'Speak in Igbo with distinct syllable breaks and a steady, slow rhythm: ' },
  'Hausa': { promptDirective: 'Speak in Hausa with a moderate, emphatic pace: ' },
};

export const generateAudio = async (text: string, language: string = 'English'): Promise<string> => {
  try {
    // Determine the directive based on the matrix
    const config = TTS_CONFIG[language] || TTS_CONFIG['English'];
    const finalPrompt = `${config.promptDirective}${text}`;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: finalPrompt }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' }, // 'Kore' provides a good neutral/analytic tone for intelligence briefings
          },
        },
      },
    });

    // Extract base64 encoded audio string
    const audioData = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (!audioData) throw new Error("No audio data returned");

    return audioData;
  } catch (error) {
    console.error("Audio Generation Error:", error);
    throw error;
  }
}

