    considerations: 'Tonal + vowel length sensitivity'
  },
  'Hausa': {
    voiceType: 'Neural',
    langCode: 'ha-NG',
    rate: '0.90 - 0.95',
    pitch: '0',
    ssmlStrategy: 'SSML for emphasis',
    considerations: 'Afro-Asiatic stress patterns'
  }
};

export const generateAudio = async (text: string, language: string = 'English'): Promise<string> => {
  try {
    const profile = TTS_MATRIX[language] || TTS_MATRIX['English'];

    // Constructing a prompt that encapsulates the Matrix requirements and the Language Isolation rule.
    // We treat the "Text to Speak" as instructions for the generative model to PERFORM the speech
    // while adhering to the user's SSML strategy and isolation requirements.
    const finalPrompt = `
      Perform the following text as high-quality speech.

      CONFIGURATION MATRIX:
      - Language: ${language}
      - Target Voice Code: ${profile.langCode}
      - Speaking Rate: ${profile.rate}
      - Pitch: ${profile.pitch}
      - Style: ${profile.ssmlStrategy}
      - Linguistic Considerations: ${profile.considerations}

      CRITICAL INSTRUCTION - LANGUAGE ISOLATION:
      - Strictly maintain the phonology and prosody of ${language} (${profile.langCode}).
      - Do not mix languages or accents. 
      - The output must be pure ${language}.
      - Treat the content as if wrapped in a single <voice xml:lang="${profile.langCode}"> block.

      TEXT TO SPEAK:
      ${text}
    `;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: finalPrompt }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' }, // 'Kore' provides a good neutral/analytic tone for intelligence briefings
          },
        },
      },
    });

    // Extract base64 encoded audio string
    const audioData = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (!audioData) throw new Error("No audio data returned");

    return audioData;
  } catch (error) {
    console.error("Audio Generation Error:", error);
    throw error;
  }
}

