import React, { useState, useEffect, useRef } from 'react';
import { QuizQuestion } from '../types';
import { CheckCircle, XCircle, AlertCircle, RefreshCw, ArrowRight, Volume2, Square, Loader2 } from 'lucide-react';
import { generateAudio } from '../services/geminiService';

interface Props {
  questions: QuizQuestion[];
  language: string;
}

// Localized feedback phrases to ensure "Language Isolation" compliance
const FEEDBACK_MAP: Record<string, { correct: string; incorrect: string }> = {
  'English': { correct: "Well done.", incorrect: "Incorrect." },
  'Nigerian Pidgin': { correct: "Well done o.", incorrect: "No be so." },
  'Yoruba': { correct: "O kare.", incorrect: "Rara, ko tọ." },
  'Igbo': { correct: "I mere ofuma.", incorrect: "Mba, ọ bụghị ya." },
  'Hausa': { correct: "Yayi kyau.", incorrect: "A'a, ba daidai bane." },
};

// Helper: Decode Base64
function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

// Helper: Decode Audio Data (PCM to AudioBuffer)
async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number = 24000,
  numChannels: number = 1,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const Quiz: React.FC<Props> = ({ questions, language }) => {
  const [currentIdx, setCurrentIdx] = useState(0);
  const [selectedOption, setSelectedOption] = useState<number | null>(null);
  const [isAnswered, setIsAnswered] = useState(false);
  const [score, setScore] = useState(0);
  const [showSummary, setShowSummary] = useState(false);

  // Audio State
  const [isAudioLoading, setIsAudioLoading] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);

  const audioCtxRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<AudioBufferSourceNode | null>(null);

  const currentQ = questions[currentIdx];

  // Cleanup audio on unmount or question change
  useEffect(() => {
    return () => stopAudio();
  }, [currentIdx]);

  const stopAudio = () => {
    if (sourceRef.current) {
        try { sourceRef.current.stop(); } catch (e) { /* ignore */ }
        sourceRef.current = null;
    }
    setIsPlaying(false);
    setIsAudioLoading(false);
  };

  const playBuffer = (buffer: AudioBuffer, ctx: AudioContext) => {
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(ctx.destination);
    source.onended = () => {
      setIsPlaying(false);
      sourceRef.current = null;
    };
    source.start();
    sourceRef.current = source;
    setIsPlaying(true);
  };

  const handleSpeakText = async (text: string) => {
    stopAudio();
    setIsAudioLoading(true);

    try {
        const base64Audio = await generateAudio(text, language);
        const pcmBytes = decodeBase64(base64Audio);

        let ctx = audioCtxRef.current;
        if (!ctx) {
            ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
            audioCtxRef.current = ctx;
        }

        const buffer = await decodeAudioData(pcmBytes, ctx, 24000, 1);
        setIsAudioLoading(false);
        playBuffer(buffer, ctx);
    } catch (e) {
        console.error("Audio generation failed", e);
        setIsAudioLoading(false);
    }
  };

  const handleReadQuestion = () => {
      if (isPlaying) {
          stopAudio();
          return;
      }
      // Construct text to read
      const textToRead = `Question ${currentIdx + 1}. ${currentQ.question}. ${currentQ.options.map((opt, i) => `Option ${i+1}: ${opt}`).join('. ')}.`;
      handleSpeakText(textToRead);
  };

  const handleOptionClick = async (idx: number) => {
    if (isAnswered) return;

    setSelectedOption(idx);
    setIsAnswered(true);

    const isCorrect = idx === currentQ.correctAnswerIndex;
    if (isCorrect) {
      setScore(prev => prev + 1);
    }

    // Interactive Audio Feedback
    // Localization strategy: Use pre-mapped phrases for "Well done" / "Incorrect"
    // to strictly adhere to the Language Isolation rules of the TTS config.
    const feedbackPhrase = isCorrect 
        ? FEEDBACK_MAP[language]?.correct || "Well done." 
        : FEEDBACK_MAP[language]?.incorrect || "Incorrect.";

    const feedbackText = `${feedbackPhrase} ${currentQ.explanation}`;

    // Auto-play feedback
    await handleSpeakText(feedbackText);
  };

  const nextQuestion = () => {
    stopAudio();
    if (currentIdx < questions.length - 1) {
      setCurrentIdx(prev => prev + 1);
      setSelectedOption(null);
      setIsAnswered(false);
    } else {
      setShowSummary(true);
    }
  };

  const resetQuiz = () => {
    stopAudio();
    setCurrentIdx(0);
    setScore(0);
    setShowSummary(false);
    setIsAnswered(false);
    setSelectedOption(null);
  };

  if (showSummary) {
    return (
      <div className="max-w-md mx-auto mt-12 glass-panel p-12 rounded-2xl text-center border border-brand-cream/10 shadow-2xl">
        <div className="w-32 h-32 mx-auto bg-brand-black rounded-full flex items-center justify-center mb-8 border-4 border-brand-red shadow-[0_0_30px_rgba(149,65,48,0.3)]">
            <span className="text-5xl font-black text-white">{Math.round((score / questions.length) * 100)}%</span>
        </div>
        <h2 className="text-3xl font-bold text-brand-cream mb-2">Assessment Complete</h2>
        <p className="text-brand-cream/60 mb-8 font-light">Dossier review score: {score} / {questions.length}</p>
        <button 
            onClick={resetQuiz}
            className="px-8 py-3 bg-brand-red text-white rounded-lg hover:bg-red-700 transition font-bold uppercase tracking-wider flex items-center justify-center gap-2 mx-auto w-full"
        >
            <RefreshCw className="w-4 h-4" /> Restart
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-2xl mx-auto py-8">
      <div className="mb-8 flex justify-between items-end">
        <div>
            <span className="text-brand-red font-mono text-xs uppercase tracking-widest block mb-1">Incoming Query</span>
            <span className="text-2xl font-bold text-brand-cream">0{currentIdx + 1} <span className="text-brand-cream/20">/ 0{questions.length}</span></span>
        </div>
        <div className="text-right">
             <span className="text-xs text-brand-cream/40 uppercase tracking-widest">Current Score</span>
             <div className="text-xl font-mono text-brand-olive">{score}</div>
        </div>
      </div>

      <div className="glass-panel p-8 rounded-2xl border border-brand-cream/10 relative overflow-hidden">
         {/* Background accent */}
         <div className="absolute -top-10 -right-10 w-40 h-40 bg-brand-red/10 rounded-full blur-3xl pointer-events-none"></div>

        <div className="relative z-10 mb-8 flex items-start gap-4">
            <h3 className="text-xl font-bold text-white leading-relaxed flex-1">{currentQ.question}</h3>

            {/* Question Reader Button */}
            <button
                onClick={handleReadQuestion}
                disabled={isAudioLoading}
                className={`shrink-0 p-3 rounded-full border transition-all duration-300 ${
                    isPlaying && !isAnswered 
                        ? 'bg-brand-red text-white border-brand-red animate-pulse' 
                        : 'bg-brand-black/40 text-brand-cream/50 border-brand-cream/10 hover:text-brand-cream hover:border-brand-cream/30'
                }`}
                title="Read Question"
            >
                {isAudioLoading && !isAnswered ? <Loader2 className="w-5 h-5 animate-spin" /> : isPlaying && !isAnswered ? <Square className="w-5 h-5 fill-current" /> : <Volume2 className="w-5 h-5" />}
            </button>
        </div>

        <div className="space-y-4 relative z-10">
          {currentQ.options.map((opt, idx) => {
            let baseStyle = "w-full text-left p-5 rounded-xl border transition-all duration-300 flex items-center justify-between group ";

            if (isAnswered) {
                if (idx === currentQ.correctAnswerIndex) {
                    baseStyle += "border-brand-olive bg-brand-olive/20 text-brand-cream shadow-[0_0_15px_rgba(104,116,81,0.3)] ";
                } else if (idx === selectedOption) {
                    baseStyle += "border-brand-red bg-brand-red/20 text-brand-red ";
                } else {
                    baseStyle += "border-transparent bg-brand-black/40 text-brand-cream/20 opacity-50 ";
                }
            } else {
                baseStyle += "border-brand-cream/5 bg-brand-black/20 hover:bg-brand-cream/5 hover:border-brand-cream/20 text-brand-cream/70 hover:text-brand-cream ";
            }

            return (
              <button
                key={idx}
                onClick={() => handleOptionClick(idx)}
                disabled={isAnswered}
                className={baseStyle}
              >
                <span className="font-light tracking-wide">{opt}</span>
                {isAnswered && idx === currentQ.correctAnswerIndex && <CheckCircle className="w-5 h-5 text-brand-olive" />}
                {isAnswered && idx === selectedOption && idx !== currentQ.correctAnswerIndex && <XCircle className="w-5 h-5 text-brand-red" />}
                {!isAnswered && <div className={`w-3 h-3 rounded-full border border-brand-cream/30 group-hover:border-brand-cream transition-colors`}></div>}
              </button>
            );
          })}
        </div>

        {isAnswered && (
          <div className="mt-8 animate-in fade-in slide-in-from-bottom-2">
            <div className="p-5 bg-brand-olive/10 rounded-xl border-l-2 border-brand-olive flex items-start gap-4 mb-6">
                <div className="shrink-0 mt-0.5 relative">
                     {isAudioLoading ? (
                        <Loader2 className="w-5 h-5 text-brand-olive animate-spin" />
                     ) : isPlaying ? (
                        <div className="w-5 h-5 flex items-center justify-center">
                            <span className="w-2 h-2 bg-brand-olive rounded-full animate-ping"></span>
                        </div>
                     ) : (
                        <AlertCircle className="w-5 h-5 text-brand-olive" />
                     )}
                </div>
                <div>
                    <p className="font-bold text-brand-olive text-xs uppercase tracking-wider mb-1 flex items-center gap-2">
                        Intel Analysis 
                        {isPlaying && <span className="text-[10px] opacity-70 font-normal normal-case animate-pulse">- Audio Playing...</span>}
                    </p>
                    <p className="text-brand-cream/80 text-sm leading-relaxed">{currentQ.explanation}</p>
                </div>
            </div>

            <div className="flex justify-end">
                <button
                    onClick={nextQuestion}
                    className="px-8 py-3 bg-brand-cream text-brand-black rounded-lg hover:bg-white transition font-bold uppercase tracking-wider shadow-lg flex items-center gap-2"
                >
                    {currentIdx < questions.length - 1 ? "Next Query" : "Complete Assessment"}
                    <ArrowRight className="w-4 h-4" />
                </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default Quiz;

