  }

  return (
    <div className="min-h-screen bg-brand-black flex flex-col font-sans text-brand-cream selection:bg-brand-red selection:text-white overflow-x-hidden">
      {/* Cinematic Header */}
      <header className="sticky top-0 z-50 glass-panel border-b-0 border-b-brand-cream/5">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-20 items-center">
            <div className="flex items-center gap-4">
              <div className="w-10 h-10 bg-brand-red rounded-none transform rotate-45 flex items-center justify-center shadow-[0_0_15px_rgba(149,65,48,0.4)]">
                 <div className="transform -rotate-45 font-black text-brand-black text-xl">K</div>
              </div>
              <div className="hidden sm:block">
                  <h1 className="text-lg font-bold text-brand-cream tracking-wider uppercase">Kachallas & Kinship</h1>
                  <p className="text-[10px] text-brand-red tracking-[0.2em] font-bold">INTERACTIVE DOSSIER</p>
              </div>
            </div>

            <nav className="flex items-center space-x-1 md:space-x-2 bg-brand-black/40 p-1.5 rounded-xl border border-brand-cream/10 backdrop-blur-md">
              <button 
                onClick={goHome}
                className="flex items-center gap-2 px-3 md:px-4 py-2 rounded-lg text-xs md:text-sm font-medium transition-all duration-300 text-brand-red hover:text-white hover:bg-brand-red/20"
                title="Return to Language Selection"
              >
                <Home className="w-4 h-4" />
                <span className="hidden md:inline">Home</span>
              </button>

              <div className="w-px h-5 bg-brand-cream/10 mx-1"></div>

              <NavButton 
                active={activeView === View.SUMMARY} 
                onClick={() => setActiveView(View.SUMMARY)} 
                icon={<BookOpen className="w-4 h-4" />}
                label="Briefing"
              />
              <NavButton 
                active={activeView === View.GRAPH} 
                onClick={() => setActiveView(View.GRAPH)} 
                icon={<Share2 className="w-4 h-4" />}
                label="Nexus"
              />
              <NavButton 
                active={activeView === View.MAP} 
                onClick={() => setActiveView(View.MAP)} 
                icon={<MapIcon className="w-4 h-4" />}
                label="Map"
              />
              <NavButton 
                active={activeView === View.QUIZ} 
                onClick={() => setActiveView(View.QUIZ)} 
                icon={<BrainCircuit className="w-4 h-4" />}
                label="Intel"
              />
              <NavButton 
                active={activeView === View.SIMULATION} 
                onClick={() => setActiveView(View.SIMULATION)} 
                icon={<Activity className="w-4 h-4" />}
                label="Sim"
              />
            </nav>
          </div>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8 relative">

        {/* Ambient background glow for content */}
        <div className="absolute top-0 left-1/2 -translate-x-1/2 w-full h-96 bg-brand-red/5 blur-[100px] pointer-events-none rounded-full"></div>

        {data && (
          <div className="transition-all duration-500 animate-in fade-in slide-in-from-bottom-4 relative z-10">
            {activeView === View.SUMMARY && <ContentReader sections={data.summarySections} language={selectedLanguage} />}
            {activeView === View.GRAPH && (
                <div className="space-y-6">
                    <div className="glass-panel p-1 rounded-2xl overflow-hidden shadow-2xl">
                        <div className="bg-brand-black/50 p-6 border-b border-brand-cream/5 flex justify-between items-center">
                            <div>
                                <h2 className="text-xl font-bold text-brand-cream tracking-wide">THE NEXUS GRAPH</h2>
                                <p className="text-xs text-brand-olive uppercase tracking-widest mt-1">Entity Relationship Visualization</p>
                            </div>
                        </div>
                        <NetworkGraph data={data.networkData} />
                    </div>
                </div>
            )}
            {activeView === View.MAP && <MapOverview data={data.mapData} />}
            {activeView === View.QUIZ && <Quiz questions={data.quiz} language={selectedLanguage} />}
            {activeView === View.SIMULATION && <Simulation initialContext={data.simulationIntro} language={selectedLanguage} />}
          </div>
        )}
      </main>
    </div>
  );
};

const NavButton: React.FC<{ active: boolean; onClick: () => void; icon: React.ReactNode; label: string }> = ({ active, onClick, icon, label }) => (
  <button
    onClick={onClick}
    className={`flex items-center gap-2 px-3 md:px-4 py-2 rounded-lg text-xs md:text-sm font-medium transition-all duration-300 ${
      active 
        ? 'bg-brand-red text-white shadow-[0_0_15px_rgba(149,65,48,0.4)]' 
        : 'text-brand-cream/60 hover:text-brand-cream hover:bg-white/5'
    }`}
  >
    {icon}
    <span className="hidden md:inline">{label}</span>
  </button>
);

export default App;
